const s=sdk.getState();
console.log('weapon', s.combatStyle.weaponName);
const cnt = {};
const log = [];
async function killOne(pattern, approach, budgetMs) {
  const deadline = Date.now()+budgetMs;
  let npc = sdk.findNearbyNpc(pattern);
  if (!npc && approach) {
    await bot.walkTo(approach[0], approach[1]).catch(()=>{});
    await sdk.waitForTicks(1);
    npc = sdk.findNearbyNpc(pattern);
  }
  if (!npc) { log.push(`nofind ${pattern}`); return false; }
  const idx = npc.index;
  try { await bot.attack(npc, 4000); } catch(e){ log.push(`atkerr ${pattern}`); }
  while (Date.now() < deadline) {
    await sdk.waitForTicks(1);
    const cur = sdk.getState();
    if (!cur) continue;
    const still = cur.nearbyNpcs.find(n=>n.index===idx && pattern.test(n.name));
    if (!still) { log.push(`KILLED ${pattern}`); cnt[pattern]=(cnt[pattern]||0)+1; return true; }
    if (cur.player.hp < 4) { log.push('lowhp'); return false; }
  }
  log.push(`timeout ${pattern}`);
  return false;
}
