  [/^imp$/i, null, 15000],
  [/^man$/i, null, 12000],
  [/^rat$/i, null, 10000],
  [/^woman$/i, [3217,3205], 15000],
  [/^giant rat$/i, [3192,3207], 15000],
];
for (const [p,a,b] of plans) { await killOne(p,a,b); }
return {log, cnt, hp: sdk.getState().player.hp};

